cand_src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row: counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for color in (value for value in counts if value != background):
        points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not points: continue
        rmin=min(r for r,c in points); rmax=max(r for r,c in points)
        cmin=min(c for r,c in points); cmax=max(c for r,c in points)
        vertical={cmin,cmax}
        for c in range(cmin+1,cmax):
            rs=[r for r,cc in points if cc==c]
            if len(rs)>=4:
                vertical.add(c)
                for r in range(min(rs),max(rs)+1):
                    if grid[r][c]==background: out[r][c]=2
        for r in range(rmin,rmax+1):
            for c in (cmin,cmax):
                if grid[r][c]==background: out[r][c]=2
        for r in range(rmin,rmax+1):
            marks=[c for rr,c in points if rr==r]
            count=len(marks)+sum(out[r][c]==2 and grid[r][c]==background for c in (cmin,cmax))
            nonvertical=sum(c not in vertical for c in marks)
            if count>=3 and nonvertical>=1:
                allmarks=sorted(set(marks+[c for c in (cmin,cmax) if out[r][c]==2]))
                for a,b in zip(allmarks,allmarks[1:]):
                    for c in range(a+1,b):
                        if grid[r][c]==background: out[r][c]=2
    return out
'''
